async function historyPage(kind,seq){if(!state.user){page(labels[kind],empty(t('Avval akkauntingizga kiring'),t('Shaxsiy bron va buyurtmalaringiz faqat sizga ko‘rinadi.'))+lh('<p><a class="primary" href="#/login">Kirish</a></p>'));return}const rows=await api('/api/'+kind);if(seq!==state.seq)return;page(labels[kind],rows.length?ht`<div class="panel">${rows.map(x=>ht`<article class="row"><div><h3>${esc(x.restaurant_name)}</h3><span class="badge">${statusName[x.status]||esc(x.status)}</span><p>${kind==='bookings'?ht`${esc(x.date)} · ${esc(x.slot)}–${esc(bookingEnd(x))} · ${x.guests} kishi · Stol ${x.table_number}`:ht`${money(x.total)} · ${x.fulfillment==='delivery'?t('Yetkazib berish'):t('Restorandan olib ketish')}`}</p>${kind==='orders'?ht`${orderProgress(x)}<p>${JSON.parse(x.items).map(i=>ht`${esc(i.name)} × ${i.quantity}`).join(', ')}</p><small>To‘lov qabul qilish vaqtida. Buyurtma holati pul to‘langanini bildirmaydi.</small>`:''}</div><div class="row-actions">${kind==='orders'?ht`<a class="quiet" href="#/tracking/${esc(x.id)}">Manzil va buyurtma →</a>`:ht`<a class="quiet" href="#/restaurant/${esc(x.restaurant_id)}">Restoran va xarita →</a>`}${(kind==='bookings'&&['pending','confirmed'].includes(x.status))||(kind==='orders'&&x.status==='pending')?ht`<button class="quiet" data-cancel="${esc(x.id)}">Bekor qilish</button>`:''}${x.status==='completed'?ht`<a class="quiet" href="#/restaurant/${esc(x.restaurant_id)}">Sharh qoldirish</a>`:''}</div></article>`).join('')}</div>`:empty(t('Hali yozuvlar yo‘q'),kind==='bookings'?t('Restoran tanlab, tashrif uchun bron yuboring.'):t('Menyudan taom tanlab, buyurtma yuboring.')));document.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=async()=>{if(!confirm(t('Bekor qilinsinmi?')))return;try{await api('/api/'+kind,'PATCH',{id:b.dataset.cancel});render()}catch(e){notify(e.message)}})}
const menuCategories=JSON.parse("[\"Salatlar\", \"Birinchi taomlar\", \"Ikkinchi taomlar\", \"Fastfood\", \"Garnirlar\", \"Gazli ichimliklar\", \"Gazsiz ichimliklar\", \"Issiq ichimliklar\", \"Desertlar\", \"Boshqalar\"]");
function menuCategory(m){const value=String(m.category||'').trim();const aliases=JSON.parse("{\"salatlar\": \"Salatlar\", \"salad\": \"Salatlar\", \"salads\": \"Salatlar\", \"салаты\": \"Salatlar\", \"salat\": \"Salatlar\", \"salat / desert\": \"Salatlar\", \"sho‘rvalar\": \"Birinchi taomlar\", \"soup\": \"Birinchi taomlar\", \"soups\": \"Birinchi taomlar\", \"супы\": \"Birinchi taomlar\", \"sho‘rva\": \"Birinchi taomlar\", \"asosiy taomlar\": \"Ikkinchi taomlar\", \"main\": \"Ikkinchi taomlar\", \"main dishes\": \"Ikkinchi taomlar\", \"основные блюда\": \"Ikkinchi taomlar\", \"asosiy taom\": \"Ikkinchi taomlar\", \"fastfood\": \"Fastfood\", \"fast food\": \"Fastfood\", \"фастфуд\": \"Fastfood\", \"garnirlar\": \"Garnirlar\", \"garnir\": \"Garnirlar\", \"sides\": \"Garnirlar\", \"гарниры\": \"Garnirlar\", \"gazli ichimliklar\": \"Gazli ichimliklar\", \"carbonated drinks\": \"Gazli ichimliklar\", \"soft drinks\": \"Gazli ichimliklar\", \"газированные напитки\": \"Gazli ichimliklar\", \"gazsiz ichimliklar\": \"Gazsiz ichimliklar\", \"still drinks\": \"Gazsiz ichimliklar\", \"негазированные напитки\": \"Gazsiz ichimliklar\", \"issiq ichimliklar\": \"Issiq ichimliklar\", \"hot drinks\": \"Issiq ichimliklar\", \"горячие напитки\": \"Issiq ichimliklar\", \"desertlar\": \"Desertlar\", \"desert\": \"Desertlar\", \"dessert\": \"Desertlar\", \"desserts\": \"Desertlar\", \"десерты\": \"Desertlar\", \"shirinlik\": \"Desertlar\", \"boshqalar\": \"Boshqalar\", \"other\": \"Boshqalar\", \"другое\": \"Boshqalar\", \"ichimlik\": \"Boshqalar\", \"ichimliklar\": \"Boshqalar\"}");return aliases[value.toLocaleLowerCase()]||value||menuCategories[menuCategories.length-1]}
function renderMenuGroups(menu){const groups=new Map();for(const m of menu){const category=menuCategory(m);if(!groups.has(category))groups.set(category,[]);groups.get(category).push(m)}const keys=[...groups.keys()].sort((a,b)=>{const ai=menuCategories.indexOf(a),bi=menuCategories.indexOf(b);return (ai<0?99:ai)-(bi<0?99:bi)});return ht`<nav class="menu-categories" aria-label="${t(t('Menyu kategoriyalari'))}"><button type="button" class="quiet active" data-menu-category="all" aria-pressed="true">${t(t('Barchasi'))}</button>${keys.map((k,i)=>ht`<button type="button" class="quiet" data-menu-category="menuCategory${i}" aria-pressed="false">${esc(t(k))} <small>${groups.get(k).length}</small></button>`).join('')}</nav>`+keys.map((k,i)=>ht`<section class="menu-category" id="menuCategory${i}"><h3>${esc(t(k))}</h3><div class="rows">${groups.get(k).map(m=>ht`<article class="food-card">${foodPicture(m)}<div class="food-info"><h3>${esc(m.name)}</h3>${m.category?ht`<span class="badge">${esc(t(menuCategory(m)))}</span>`:''}<p>${esc(m.description||'')}</p><p>${money(m.price)}</p><span class="badge">${m.available?t('Hozir mavjud'):t('Hozir mavjud emas')}</span>${m.ingredients?ht`<small>Tarkibi: ${esc(m.ingredients)}</small><br>`:''}<small>Allergenlar: ${esc(m.allergens||t('Restorandan aniqlashtiring'))}</small></div><label class="menu-quantity"><span class="muted">Soni</span><span class="quantity-stepper"><button type="button" data-qty-step="-1" aria-label="${esc(t(t('Kamaytirish')))}" ${m.available?'':'disabled'}>−</button><input class="qty" name="${esc(m.id)}" type="number" min="0" max="20" value="0" ${m.available?'':'disabled'} aria-label="${esc(m.name)} soni"><button type="button" data-qty-step="1" aria-label="${esc(t(t('Ko‘paytirish')))}" ${m.available?'':'disabled'}>+</button></span></label></article>`).join('')}</div></section>`).join('')}
function bindMenuCategories(){document.querySelectorAll('[data-menu-category]').forEach(button=>button.onclick=()=>{const key=button.dataset.menuCategory;document.querySelectorAll('.menu-category').forEach(section=>section.hidden=key!=='all'&&section.id!==key);document.querySelectorAll('[data-menu-category]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))})});document.querySelectorAll('[data-qty-step]').forEach(button=>button.onclick=()=>{const input=button.closest('.quantity-stepper').querySelector('input');if(input.disabled)return;input.value=Math.max(0,Math.min(20,(Number(input.value)||0)+Number(button.dataset.qtyStep)));input.dispatchEvent(new Event('input',{bubbles:true}))})}

async function restaurant(id,seq){await loadCatalog();const r=state.catalog.find(x=>x.id===id);if(seq!==state.seq)return;if(!r){page(t('Restoran'),empty(t('Restoran mavjud emas'),t('U vaqtincha yopilgan yoki hali katalogga qo‘shilmagan.')));return}const menu=state.menu.filter(m=>m.restaurant_id===id);page(r.name,ht`${r.id.startsWith('rf-demo-')?lh('<p class="notice">DEMO: haqiqiy xizmat ko‘rsatilmaydi. Buyurtma va bronlar faqat sinov uchun.</p>'):''}<a class="link back" href="#/discover">← Restoranlar</a><p>${esc(r.description)}</p><p>${esc(r.address)} · <a href="tel:${esc(r.phone)}">${esc(r.phone)}</a></p><p>${rating(r)}</p>${r.image_url?ht`<img class="restaurant-hero" src="${esc(r.image_url)}" alt="${esc(r.name)}" referrerpolicy="no-referrer">`:''}<p>Ish vaqti: ${esc(r.hours||t('Restorandan aniqlashtiring'))}</p>${mapCard(r.latitude,r.longitude,r.address)}${serviceChoices(r)}<div class="split"><div><section class="panel"><h2>Menyu</h2>${menu.length?ht`<form id="orderForm"><div class="rows">${renderMenuGroups(menu)}</div><p id="orderTotal">Jami: 0 so‘m</p><div class="form"><label>TELEFON<input id="orderPhone" type="tel" placeholder="+998901234567" pattern="\\+998[0-9]{9}" required></label><label>BUYURTMA TURI<select id="fulfillment"><option value="pickup">Restorandan olib ketish</option>${r.delivery_enabled?ht`<option value="delivery">Yetkazib berish (+${money(r.delivery_fee)})</option>`:''}</select></label><div id="deliveryFields" hidden><label>YETKAZIB BERISH MANZILI<input id="deliveryAddress" maxlength="300" placeholder="Ko‘cha, uy, xonadon va mo‘ljal"></label>${coordinateFields('delivery')}<p>Telefoningiz manzilida bo‘lsangiz GPS tugmasini bosing. Boshqa manzil uchun koordinatalarni kiriting.</p></div><p class="notice">Buyurtma restoran tomonidan tasdiqlanadi. To‘lov qabul qilish vaqtida; onlayn to‘lov hozircha ulanmagan.</p><button class="primary">Buyurtma yuborish</button><p id="orderMessage" class="form-message" role="status"></p></div></form>`:empty(t('Menyu hali kiritilmagan'),t('Taomlar va haqiqiy narxlar restoran tomonidan qo‘shiladi.'))}</section><section class="panel" id="reviews"><h2>Xaridorlar sharhlari</h2><p>Sharhlar yuklanmoqda…</p></section></div><section class="panel booking-panel" id="bookingPlan"><h2>Stolni xaritadan tanlang</h2><p>Joylar yuklanmoqda…</p></section></div>`);
 if(r.is_demo||r.id.startsWith('rf-demo-')){let gallery=[];try{gallery=JSON.parse(r.gallery||'[]')}catch{}const plan=$('#bookingPlan')?.closest('.split');if(plan&&gallery.length)plan.insertAdjacentHTML('beforebegin',lh('<div class="demo-gallery">')+gallery.filter(u=>/^\/demo-assets\/[a-z-]+\.jpg$/.test(u)).map(u=>lh('<img loading="lazy" src="')+esc(u)+'" alt="DEMO — illustrative interior">').join('')+lh('</div><p class="muted">DEMO · Illustrative photos / Tasviriy rasmlar / Иллюстративные фото</p>'));document.querySelectorAll('[data-add-cart]').forEach(b=>{b.disabled=true;b.textContent='DEMO'});}
bindFoodImages();bindMenuCart(r,menu);bindMenuCategories();bindServiceChoices();
 bindCoordinateButtons();await bookingPlan(id,r,seq);await reviews(id,seq);
}
async function reviews(id,seq){const d=await api('/api/reviews?restaurantId='+encodeURIComponent(id));if(seq!==state.seq||!$('#reviews'))return;$('#reviews').innerHTML=ht`<h2>Xaridorlar sharhlari</h2><p class="rating">${d.summary.count?ht`★ ${Number(d.summary.average).toFixed(1)} / 5 · ${d.summary.count} ta baho`:t('Hali baho yo‘q')}</p>${d.reviews.map(v=>ht`<article class="review"><strong>${esc(v.name)}</strong> <span class="rating" aria-label="5 dan ${v.stars}">${'★'.repeat(v.stars)}${'☆'.repeat(5-v.stars)}</span><p>${esc(v.comment)}</p><small>${esc(v.updated_at.slice(0,10))} · ${v.is_demo?t('Demo sharh'):'Tasdiqlangan xaridor'}</small></article>`).join('')}${d.eligible?ht`<h3 style="margin-top:25px">${d.mine?t('Bahoyingizni yangilang'):t('Sizning fikringiz')}</h3><form id="reviewForm" class="form"><fieldset class="stars"><legend>1 dan 5 gacha baholang</legend>${[1,2,3,4,5].map(n=>ht`<label class="star-option"><input type="radio" name="stars" value="${n}" ${d.mine?.stars===n?'checked':''} required aria-label="${n} yulduz">${n}★</label>`).join('')}</fieldset><label>SHARHINGIZ<textarea name="comment" minlength="3" maxlength="1000" required placeholder="Taom, xizmat va taassurotlaringiz haqida yozing">${esc(d.mine?.comment||'')}</textarea></label><button class="primary">${d.mine?t('Sharhni yangilash'):t('Sharhni yuborish')}</button>${d.mine?lh('<button class="quiet" type="button" id="deleteReview">Sharhimni o‘chirish</button>'):''}<p id="reviewMessage" class="form-message" role="status"></p></form>`:lh('<p class="notice">Shu restorandagi bron yoki buyurtmangiz yakunlangach, xaridor sifatida 1–5 yulduzli baho va sharh qoldirishingiz mumkin.</p>')}`;
 if($('#reviewForm'))$('#reviewForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button.primary'),b=Object.fromEntries(new FormData(e.currentTarget));button.disabled=true;try{await api('/api/reviews','POST',{restaurantId:id,stars:Number(b.stars),comment:b.comment});notify(t('Sharhingiz saqlandi.'));await reviews(id,seq)}catch(e){$('#reviewMessage').textContent=e.message;button.disabled=false}};
 if($('#deleteReview'))$('#deleteReview').onclick=async()=>{if(!confirm(t('Sharhingiz o‘chirilsinmi?')))return;try{await api('/api/reviews','DELETE',{restaurantId:id});await reviews(id,seq)}catch(e){notify(e.message)}};
}
function account(){if(!state.user){location.hash='/login';return}page(t('Profil'),ht`<div class="panel compact profile-panel"><h3>${esc(state.user.name)}</h3><p>${esc(state.user.email||state.user.phone)}</p><p>${state.user.emailVerified?t('Email tasdiqlangan.'):t('Telefon tasdiqlangan.')} <strong>${roleLabel(state.user.role)}</strong></p><div class="separator"></div><h3>Aloqa raqami</h3><form id="contactPhoneForm" class="form contact-phone-form"><label>TELEFON<input name="contactPhone" type="tel" inputmode="tel" autocomplete="tel" maxlength="22" placeholder="+998 XX XXX XX XX" value="${esc(state.user.contactPhone||'')}"></label><p>Bu aloqa raqami. SMS tasdiqlash va raqam bilan kirish keyin qo‘shiladi.</p><div class="contact-phone-actions"><button class="primary" type="submit">Saqlash</button><button class="quiet" type="button" id="removeContactPhone">Raqamni o‘chirish</button></div><p id="contactPhoneMessage" role="status"></p></form>${languageSelect()}<a class="primary" href="#${homeFor(state.user)}">Panelni ochish →</a>${state.user.email?lh('<div class="separator"></div><h3>Parolni o‘zgartirish</h3><p>Emailingizga kelgan kod va yangi parol talab qilinadi.</p><a class="quiet" id="changePassword" href="#/forgot">Tasdiqlash kodi bilan o‘zgartirish</a>'):lh('<p>Telefon bilan kirishda har safar SMS kodi ishlatiladi.</p>')}${state.user.role==='customer'?lh('<div class="separator"></div><h3>Hamkorlik uchun ariza</h3><p>Restoran yoki kuryer sifatida ishlash uchun administrator tasdig‘i kerak.</p><form id="accessRequest" class="form"><label>FAOLIYAT<select name="role"><option value="restaurant_owner">Restoran egasi</option><option value="courier">Kuryer</option></select></label><label>MA’LUMOT<textarea name="note" minlength="5" maxlength="1000" required></textarea></label><button class="quiet">Ariza yuborish</button></form>'):''}</div>`);bindLanguageSelect();const phoneForm=$('#contactPhoneForm'),phoneInput=phoneForm.elements.contactPhone;phoneInput.oninput=()=>{let v=phoneInput.value.replace(/\D/g,'');if(v.startsWith('998'))v=v.slice(3);v=v.slice(0,9);phoneInput.value=v?'+998 '+[v.slice(0,2),v.slice(2,5),v.slice(5,7),v.slice(7,9)].filter(Boolean).join(' '):''};const savePhone=async value=>{const buttons=phoneForm.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);try{const result=await api('/api/profile','POST',{action:'contact-phone',phone:value});state.user.contactPhone=result.contactPhone;phoneInput.value=result.contactPhone;$('#contactPhoneMessage').textContent=t(t('Aloqa raqami saqlandi.'))}catch(e){$('#contactPhoneMessage').textContent=e.message}finally{buttons.forEach(b=>b.disabled=false)}};phoneForm.onsubmit=e=>{e.preventDefault();savePhone(phoneInput.value)};$('#removeContactPhone').onclick=()=>savePhone('');if($('#changePassword'))$('#changePassword').onclick=()=>{state.authEmail=state.user.email;state.authMode='change'};if($('#accessRequest'))$('#accessRequest').onsubmit=async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{await api('/api/profile','POST',{action:'request-access',...Object.fromEntries(new FormData(e.currentTarget))});notify(t('Ariza yuborildi. Administrator ko‘rib chiqadi.'))}catch(err){notify(err.message)}finally{b.disabled=false}};}
async function admin(seq){if(state.user?.role!=='admin'){page(t('Admin panel'),empty(t('Ruxsat yo‘q'),t('Bu bo‘lim faqat sayt administratoriga ochiq.')));return}page(t('Admin panel'),ht`<p>Faqat haqiqiy yozuvlar. Yakunlangan buyurtma avtomatik ravishda to‘langan hisoblanmaydi.</p><div class="row-actions"><a class="primary" href="#/manage">Restoranlarni boshqarish →</a><a class="quiet" href="#/blog-admin">Blog boshqaruvi</a></div><div class="panel"><label>HISOBOT DAVRI<select id="period"><option value="7">Oxirgi 7 kun</option><option selected value="30">Oxirgi 30 kun</option><option value="365">Oxirgi 365 kun</option><option value="all">Barcha vaqt</option></select></label></div><div id="adminReport"></div><section id="accountManagement" class="panel"></section>`);const report=async()=>{try{const d=await api('/api/admin?days='+$('#period').value);if(seq!==state.seq)return;const t=d.totals;$('#adminReport').innerHTML=ht`<div class="metric-grid"><div class="metric"><small>Tasdiqlangan to‘lovlar</small><strong>${money(t.gross)}</strong></div><div class="metric"><small>Qaytarishlar</small><strong>${money(t.refunds)}</strong></div><div class="metric"><small>Platforma komissiyasi</small><strong>${money(t.commission)}</strong></div></div><p class="notice">Onlayn to‘lov hali ulanmagan. Restoran sof foydasi uchun xarajatlar ham hisobga olinishi kerak.</p><div class="panel"><h3>Restoranlar kesimida</h3>${d.restaurants.length?ht`<div class="table-wrap"><table><thead><tr><th>Restoran</th><th>Holat</th><th>To‘lovlar</th><th>Qaytarish</th><th>Komissiya</th><th>Tushum</th></tr></thead><tbody>${d.restaurants.map(r=>ht`<tr><td>${esc(r.name)}</td><td>${statusName[r.status]||esc(r.status)}</td><td>${money(r.gross)}</td><td>${money(r.refunds)}</td><td>${money(r.commission)}</td><td>${money(r.gross-r.refunds-r.commission)}</td></tr>`).join('')}</tbody></table></div>`:lh('<p>Hali restoranlar qo‘shilmagan.</p>')}</div>`;await adminAccounts(seq)}catch(e){notify(e.message)}};$('#period').onchange=report;await report();}
async function manage(seq){if(!['admin','restaurant_owner'].includes(state.user?.role)){page(t('Restoran kabineti'),empty(t('Ruxsat yo‘q'),t('Restoran egasini administrator tasdiqlaydi.')));return}const d=await api('/api/manage');if(seq!==state.seq)return;const actions=(items,kind)=>items.map(x=>ht`<article class="row"><div><h3>${esc(x.restaurant_name)}</h3><span class="badge">${statusName[x.status]}</span><p>${kind==='booking'?ht`${esc(x.date)} · ${esc(x.slot)}–${esc(bookingEnd(x))} · ${x.guests} kishi`:ht`${money(x.total)} · ${JSON.parse(x.items).map(i=>esc(i.name)+' × '+i.quantity).join(', ')}`}</p><a href="tel:${esc(x.phone)}">${esc(x.phone)}</a></div><div class="row-actions">${kind==='order'?ht`<a class="quiet" href="#/tracking/${esc(x.id)}">Manzil / kuryer →</a>`:''}${x.status==='pending'?ht`<button class="primary" data-kind="${kind}" data-id="${x.id}" data-status="confirmed">Tasdiqlash</button>`:''}${x.status==='confirmed'&&!(kind==='order'&&x.fulfillment==='delivery')?ht`<button class="primary" data-kind="${kind}" data-id="${x.id}" data-status="completed">Yakunlandi</button>`:''}${['pending','confirmed'].includes(x.status)?ht`<button class="quiet" data-kind="${kind}" data-id="${x.id}" data-status="cancelled">Bekor qilish</button>`:''}</div></article>`).join('');
 page(t('Restoran kabineti'),ht`<div class="panel"><h3>Restoranlar</h3><select id="managedRestaurant"><option value="">Yangi restoran qo‘shish</option>${d.restaurants.map(r=>ht`<option value="${r.id}">${esc(r.name)}</option>`).join('')}</select><p>Yangi restoran administrator tasdiqlagach katalogda ko‘rinadi.</p><div id="restaurantEditor"></div></div><section class="panel" id="tableEditor"><h3>Qavatlar va stollar</h3><p>Avval restoranni saqlang yoki tanlang.</p></section><div class="panel"><h3>Menyu</h3><p>Avval restoranni saqlang, keyin menyusini kiriting.</p><div id="menuEditor"></div></div><div class="panel"><h3>Bronlar</h3>${actions(d.bookings,'booking')||lh('<p>Hali bronlar yo‘q.</p>')}</div><div class="panel"><h3>Buyurtmalar</h3><p>“Yakunlandi” — xizmat ko‘rsatilganini bildiradi. Bu pul tushumini avtomatik tasdiqlamaydi.</p>${actions(d.orders,'order')||lh('<p>Hali buyurtmalar yo‘q.</p>')}</div>`);
 const editor=()=>{let selected=$('#managedRestaurant').value;const r=d.restaurants.find(x=>x.id===selected);$('#restaurantEditor').innerHTML=ht`<form id="restaurantForm" class="form" style="margin-top:20px"><div class="two"><label>NOMI<input name="name" value="${esc(r?.name||'')}" required maxlength="100"></label><label>TELEFON<input name="phone" value="${esc(r?.phone||'')}" pattern="\\+998[0-9]{9}" placeholder="+998901234567" required></label></div><label>MANZIL<input name="address" value="${esc(r?.address||'')}" required minlength="5" maxlength="300"></label>${coordinateFields('restaurant',r?.latitude,r?.longitude)}${photoInput("restaurantPhoto",r?.image_url)}<label>ISH VAQTI<input name="hours" maxlength="200" value="${esc(r?.hours||'')}" placeholder="Har kuni 09:00–23:00"></label><label class="check"><input name="deliveryEnabled" type="checkbox" ${r?.delivery_enabled?'checked':''}> Yetkazib berish xizmati bor</label><label>YETKAZIB BERISH NARXI (SO‘M)<input name="deliveryFee" type="number" min="0" max="1000000" value="${r?.delivery_fee||0}"></label><label>Taxminiy yetkazish vaqti (daqiqa)<input name="deliveryMinutes" type="number" min="5" max="240" value="${r?.delivery_minutes??''}"></label><label>TA’RIF<textarea name="description" maxlength="1500">${esc(r?.description||'')}</textarea></label><label>OSHXONA TURI<input name="cuisine" value="${esc(r?.cuisine||'')}" maxlength="60"></label><div class="two"><label>BRON UCHUN STOLLAR SONI<input name="tables" type="number" min="0" max="50" value="${r?.tables||0}" required></label><label>QAVATLAR SONI<input name="floors" type="number" min="1" max="10" value="${r?.floors||1}" required></label></div><div class="two"><label>ZAL ENI (METR)<input name="hallWidth" type="number" min="2" max="200" step="0.1" value="${r?.hall_width??''}" placeholder="Masalan: 12" required></label><label>ZAL BO‘YI (METR)<input name="hallLength" type="number" min="2" max="200" step="0.1" value="${r?.hall_length??''}" placeholder="Masalan: 8" required></label></div><p>Qavat rejasi shu to‘rtburchak zal nisbatida chiziladi. Stollar joyini keyingi bosqichda bosib belgilang.</p><div class="two"><label>BRON BOSHLANISHI<input name="bookingOpen" type="time" value="${r?.booking_open||'09:00'}" required></label><label>BRON TUGASHI<input name="bookingClose" type="time" value="${r?.booking_close||'23:00'}" required></label></div><p>Restoranni saqlagach, har bir stolning sig‘imi, qavati, rasmi va joylashuvini pastdagi rejada alohida qo‘shing.</p>${state.user.role==='admin'?ht`<label>HOLATI<select name="status">${['pending','active','paused','rejected'].map(s=>ht`<option value="${s}" ${(r?.status||'pending')===s?'selected':''}>${statusName[s]}</option>`).join('')}</select><label>RESTORAN EGASINING TASDIQLANGAN EMAILI (IXTIYORIY)<input name="ownerEmail" type="email" placeholder="Avval akkaunt yaratgan bo‘lishi kerak"></label>`:''}<label class="check"><input type="checkbox" required> Ma’lumotlar haqiqiy va restoran roziligi bilan kiritilgan.</label><button class="primary">Restoranni saqlash</button><p class="form-message" id="restaurantMessage" role="status"></p></form>`;
 $('#restaurantForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('button.primary');button.disabled=true;try{const saved=await api('/api/manage','POST',{...b,id:selected||undefined,action:'restaurant',tables:Number(b.tables),floors:Number(b.floors),hallWidth:Number(b.hallWidth),hallLength:Number(b.hallLength),imageUrl:r?.image_url||'',latitude:readCoord('restaurantLat'),longitude:readCoord('restaurantLng'),deliveryEnabled:b.deliveryEnabled==='on',deliveryFee:Number(b.deliveryFee),deliveryMinutes:b.deliveryMinutes?Number(b.deliveryMinutes):null});state.managedRestaurant=saved.id;selected=saved.id;const file=$('#restaurantPhoto').files[0];if(file){const url=await uploadPhoto(file,saved.id);await api('/api/manage','POST',{action:'image',restaurantId:saved.id,imageUrl:url})}notify(t('Restoran saqlandi. Endi stollarni alohida qo‘shishingiz mumkin.'));render()}catch(e){$('#restaurantMessage').textContent=e.message;button.disabled=false}};
 bindCoordinateButtons();bindPhotoInputs();if(r)tableManager(r,seq);else $('#tableEditor').innerHTML=lh('<h3>Qavatlar va stollar</h3><p>Avval restoranni saqlang.</p>');if(r)$('#restaurantEditor').insertAdjacentHTML('afterbegin',ht`<p>${statusName[r.status]} · ${rating(r)}</p>${mapCard(r.latitude,r.longitude,r.address)}${r.status==='active'?ht`<a class="link" href="#/restaurant/${esc(r.id)}">Restoran sahifasi va sharhlar →</a>`:''}`);if(!r){$('#menuEditor').innerHTML=lh('<p>Saqlangan restoranni tanlang.</p>');return}const dishes=d.menu.filter(m=>m.restaurant_id===r.id);$('#menuEditor').innerHTML=ht`<select id="dishSelect"><option value="">Yangi taom</option>${dishes.map(m=>ht`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select><div id="dishFormHost"></div>`;const dishEditor=()=>{const m=dishes.find(m=>m.id===$('#dishSelect').value);$('#dishFormHost').innerHTML=ht`<form id="dishForm" class="form" style="margin-top:20px"><label>TAOM NOMI<input name="name" value="${esc(m?.name||'')}" required maxlength="100"></label><label>NARX (SO‘M)<input name="price" type="number" min="0" max="10000000" value="${m?.price??''}" required></label><label>TAVSIF<textarea name="description" maxlength="1500">${esc(m?.description||'')}</textarea></label><label>KATEGORIYA<input name="category" list="menuCategoryOptions" maxlength="100" value="${esc(m?.category||'')}"><datalist id="menuCategoryOptions">${menuCategories.map(k=>ht`<option value="${esc(k)}">${esc(t(k))}</option>`).join('')}</datalist></label>${foodUploadFields(m)}<label>TARKIBI<textarea name="ingredients" maxlength="1000">${esc(m?.ingredients||'')}</textarea></label><label>ALLERGENLAR<input name="allergens" value="${esc(m?.allergens||'')}" maxlength="500"></label><label class="check"><input name="available" type="checkbox" ${!m||m.available?'checked':''}> Hozir mavjud</label><button class="primary">Taomni saqlash</button><p class="form-message" role="status" id="dishMessage"></p></form>`;const imageEditor=bindFoodUpload(m);$('#dishForm').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget)),button=e.currentTarget.querySelector('button.primary');button.disabled=true;try{const imageUrl=await imageEditor.save(r.id);await api('/api/manage','POST',{...b,imageUrl,id:m?.id,action:'menu',restaurantId:r.id,price:Number(b.price),available:b.available==='on'});notify(t('Taom saqlandi.'));render()}catch(e){$('#dishMessage').textContent=e.message;button.disabled=false}}};$('#dishSelect').onchange=dishEditor;dishEditor();};if(state.managedRestaurant&&d.restaurants.some(r=>r.id===state.managedRestaurant))$('#managedRestaurant').value=state.managedRestaurant;$('#managedRestaurant').onchange=()=>{state.managedRestaurant=$('#managedRestaurant').value;editor()};editor();
 document.querySelectorAll('[data-status]').forEach(b=>b.onclick=async()=>{if(!confirm(t('Holat “')+statusName[b.dataset.status]+t('” bo‘lsinmi?')))return;b.disabled=true;try{await api('/api/manage','POST',{action:'status',kind:b.dataset.kind,id:b.dataset.id,status:b.dataset.status});render()}catch(e){notify(e.message);b.disabled=false}});
}
function settings(){page(t('Sozlamalar'),ht`<div class="settings-grid"><section class="panel settings-panel"><h3>Til va hudud</h3><div class="settings-field"><p>Sayt tili</p>${languageSelect()}</div><p>Bron vaqtlari: Samarqand (UTC+5).</p><p class="muted">Tungi va kunduzgi rejim yon menyuning pastida.</p></section><section class="panel settings-panel"><h3>Akkaunt va xavfsizlik</h3><div class="settings-links"><a class="quiet" href="#/${state.user?'account':'login'}">${state.user?t('Profil'):t('Kirish')} <span aria-hidden="true">→</span></a>${state.user?.email?lh('<a class="quiet" id="settingsPassword" href="#/forgot">Parolni o‘zgartirish <span aria-hidden="true">→</span></a>'):''}</div></section><section class="panel settings-panel"><h3>Yordam va maxfiylik</h3><div class="settings-links"><a class="quiet" href="#/support">Yordam va aloqa <span aria-hidden="true">→</span></a><a class="quiet" href="#/privacy">Maxfiylik siyosati <span aria-hidden="true">→</span></a><a class="quiet" href="#/terms">Foydalanish shartlari <span aria-hidden="true">→</span></a></div></section></div>`);$('#content').insertAdjacentHTML('beforeend',ht`<section class="panel demo-settings"><h3>DEMO</h3><label><input type="checkbox" id="demoVisibility" ${localStorage.getItem('rf-show-demo')!=='false'?'checked':''}> ${dt('showDemo')}</label>${state.user?.role==='admin'?ht`<p><button id="demoGlobalOn" class="quiet">${dt('demoOn')}</button> <button id="demoGlobalOff" class="quiet">${dt('demoOff')}</button></p>`:''}<p id="demoSettingsMessage" role="status"></p></section>`);$('#demoVisibility').onchange=e=>localStorage.setItem('rf-show-demo',String(e.target.checked));['On','Off'].forEach(k=>{const b=$('#demoGlobal'+k);if(b)b.onclick=async()=>{try{await api('/api/demo-room','POST',{action:'settings',enabled:k==='On'});$('#demoSettingsMessage').textContent=dt(k==='On'?'demoOn':'demoOff')}catch(e){$('#demoSettingsMessage').textContent=demoError(e)}}});bindLanguageSelect();if($('#settingsPassword'))$('#settingsPassword').onclick=()=>{state.authEmail=state.user.email;state.authMode='change'}}
async function render(){const landing=document.getElementById('seoLanding');if(landing)landing.hidden=true;captchaDispose();stopTracking();const seq=++state.seq,route=routeName();let robots=document.querySelector('meta[name=robots]');if(!robots){robots=document.createElement('meta');robots.name='robots';document.head.appendChild(robots)}robots.content=location.hash?'noindex,follow':'index,follow';document.title=t(labels[route]||'RestaurantFoods')+' — RestaurantFoods';if(['login','signup','forgot','verify','reset','admin-login'].includes(route)){if($('#mobileNav'))$('#mobileNav').hidden=true;authScreen(route);return}$('#auth').hidden=true;$('#topbar').hidden=false;$('#content').hidden=false;$('#pageName').textContent=labels[route]||t('Restoran');navigation();mobileNavigation();$('#content').innerHTML=lh('<div class="market-loading" role="status"><span class="loading-ring" aria-hidden="true"></span><p>Yuklanmoqda…</p></div>');window.scrollTo(0,0);try{if(route==='discover'||route==='search')await discover(seq);else if(route==='cart')await cartPage(seq);else if(route==='restaurant')await restaurant(decodeURIComponent(location.hash.split('/')[2]||''),seq);else if(['bookings','orders'].includes(route))await historyPage(route,seq);else if(route==='account')account();else if(route==='admin')await admin(seq);else if(route==='blog-admin')await blogAdmin(seq);else if(route==='manage')await manage(seq);else if(route==='courier')await courierPanel(seq);else if(route==='tracking')await trackingPage(decodeURIComponent(location.hash.split('/')[2]||''),seq);else if(route==='invite')await invitePage(seq);else if(route==='privacy'||route==='terms')legalPage(route);else if(route==='settings')settings();else if(route==='billing')page(t('Billing va to‘lovlar'),empty(t('Onlayn to‘lov hali yoqilmagan'),t('Buyurtmalar uchun restoranda to‘lanadi. Bu sahifada soxta tranzaksiya yoki depozit ko‘rsatilmaydi.')));else if(route==='support')page(t('Support — Aloqa'),ht`<p>Akkaunt, bron, buyurtma yoki restoran hamkorligi bo‘yicha biz bilan bog‘laning.</p><div class="two"><section class="panel"><p class="eyebrow">TELEFON</p><h2 style="font-size:25px">+998 99 384 73 84</h2><p>Telefon orqali murojaat qilish uchun quyidagi tugmani bosing.</p><a class="primary" href="tel:+998993847384">Qo‘ng‘iroq qilish</a></section><section class="panel"><p class="eyebrow">EMAIL</p><h2 style="font-size:clamp(16px,3vw,25px);overflow-wrap:anywhere">furqatovm2007@gmail.com</h2><p>Savol yoki taklifingizni email orqali yuboring.</p><a class="primary" href="mailto:furqatovm2007@gmail.com?subject=RestaurantFoods%20Support">Email yozish</a></section></div><div class="panel compact"><h3>Murojaatingizda nimalarni yozish kerak?</h3><p>Restoran nomi, bron yoki buyurtma sanasi va muammo tavsifini kiriting. Parol va tasdiqlash kodlarini yubormang.</p></div>`);else if(route==='help')page(t('Yordam'),ht`<div class="panel compact"><h3>Bron qanday ishlaydi?</h3><p>Restoran, sana, boshlanish va tugash vaqtini tanlang. Qavat rejasidagi bo‘sh stolni bosib bron yuboring. So‘rov tasdiqlangach, Bronlarim bo‘limida holati yangilanadi. Bekor qilish ham shu bo‘limda.</p><h3>Buyurtma va to‘lov</h3><p>Buyurtma tasdiqlangach, restorandan olib ketiladi. To‘lov joyida. Yetkazib berishni yoqqan restoranlarda manzil bilan buyurtma berish mumkin. Tasdiqlangan kuryer biriktirilgach, buyurtma sahifasida kuzating. Onlayn to‘lov va SMS eslatma hali ulanmagan.</p><h3>Sharhlar</h3><p>Yakunlangan bron yoki buyurtmasi bor xaridor bir restoranga bitta 1–5 yulduzli baho va sharh qoldiradi. O‘z sharhingizni keyin yangilashingiz yoki o‘chirishingiz mumkin.</p></div>`);else{location.hash='/discover'}}catch(e){if(seq===state.seq)page(t('Yuklashda xatolik'),empty(t('Ma’lumot yuklanmadi'),e.message)+lh('<p><button class="primary" id="retry">Qayta urinish</button></p>'));if($('#retry'))$('#retry').onclick=render;}}
window.addEventListener('hashchange',render);
(async()=>{setInterval(()=>{if(state.user&&document.visibilityState==='visible')renewSession()},45*60*1000);document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&state.user)renewSession()});try{document.body.dataset.theme=localStorage.getItem('rf-theme')||'dark'}catch{}render();try{const [config,me]=await Promise.all([api('/api/auth/config'),api('/api/me')]);state.config=config;state.user=me.user;if(!state.user&&await renewSession())state.user=(await api('/api/me')).user;if(state.user&&!location.hash){const after=sessionStorage.getItem('rf-after-login');if(after&&/^#\/(restaurant\/|cart$|bookings$|discover$)/.test(after)){sessionStorage.removeItem('rf-after-login');location.hash=after}}if(state.user&&!requestedLanguage)RF_I18N.set(state.user.preferredLanguage||'ru')}catch(e){notify(e.message)}render()})();

function roleLabel(role){return {customer:t('Mijoz'),restaurant_owner:t('Restoran egasi'),courier:t('Kuryer'),admin:t('Administrator')}[role]||t('Mijoz')}
function homeFor(user){return {admin:'/admin',restaurant_owner:'/manage',courier:'/courier'}[user.role]||'/discover'}
function readCoord(id){const v=$('#'+id)?.value;return v===undefined||v===''?null:Number(v)}
function coordinateFields(prefix,lat=null,lng=null){return ht`<div class="two"><label>KENGLIK (LATITUDE)<input id="${prefix}Lat" type="number" step="any" min="-90" max="90" value="${lat??''}" placeholder="39.65..."></label><label>UZUNLIK (LONGITUDE)<input id="${prefix}Lng" type="number" step="any" min="-180" max="180" value="${lng??''}" placeholder="66.96..."></label></div><div class="row-actions"><button type="button" class="quiet" data-location="${prefix}">⌖ Hozirgi joyimni GPS orqali olish</button><button type="button" class="quiet" data-preview="${prefix}">Xaritada tekshirish</button></div><div id="${prefix}Map"></div>`}
function bindCoordinateButtons(){document.querySelectorAll('[data-location]').forEach(b=>b.onclick=()=>{if(!navigator.geolocation){notify(t('Bu brauzer GPSni qo‘llamaydi.'));return}b.disabled=true;navigator.geolocation.getCurrentPosition(p=>{$('#'+b.dataset.location+'Lat').value=p.coords.latitude.toFixed(6);$('#'+b.dataset.location+'Lng').value=p.coords.longitude.toFixed(6);$('#'+b.dataset.location+'Map').innerHTML=mapCard(p.coords.latitude,p.coords.longitude,t('Tanlangan joy'));b.disabled=false;notify(t('Joy olindi. Manzil matnini ham kiriting.'))},()=>{b.disabled=false;notify(t('GPSga ruxsat bering yoki koordinatalarni qo‘lda kiriting.'))},{enableHighAccuracy:true,timeout:15000,maximumAge:0})});document.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>{$('#'+b.dataset.preview+'Map').innerHTML=mapCard(readCoord(b.dataset.preview+'Lat'),readCoord(b.dataset.preview+'Lng'),t('Tanlangan joy'))})}
function mapCard(lat,lng,address){const valid=typeof lat==='number'&&typeof lng==='number'&&Number.isFinite(lat)&&Number.isFinite(lng)&&Math.abs(lat)<=90&&Math.abs(lng)<=180;const destination=valid?lat+','+lng:address;if(!valid)return ht`<p class="muted">Aniq xarita nuqtasi hali kiritilmagan.</p>${address?ht`<a class="quiet" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(address)}">Manzilni xaritadan qidirish ↗</a>`:''}`;const box=[Math.max(-180,lng-.008),Math.max(-90,lat-.005),Math.min(180,lng+.008),Math.min(90,lat+.005)].join(',');return ht`<div class="map-card"><iframe title="${esc(address||t('Joylashuv xaritasi'))}" loading="lazy" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=${encodeURIComponent(box)}&layer=mapnik&marker=${lat}%2C${lng}"></iframe><a class="quiet" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/dir/?api=1&destination=${encodeURIComponent(destination)}">Yo‘nalishni ochish ↗</a></div>`}
async function courierPanel(seq){if(state.user?.role!=='courier'){page(t('Kuryer paneli'),empty(t('Kuryer profili kerak'),t('Profil turini tekshiring.')));return}const d=await api('/api/delivery');if(seq!==state.seq)return;page(t('Kuryer paneli'),ht`<p>Salom, ${esc(state.user.name)}. Sizga biriktirilgan faol yetkazib berishlar.</p>${!d.approved?lh('<div class="panel"><h2>Tasdiq kutilmoqda</h2><p>Administrator akkauntingizni tasdiqlagach buyurtmalar olishingiz mumkin.</p><a class="quiet" href="#/support">Support bilan bog‘lanish</a></div>'):ht`<div class="metric"><small>Faol buyurtmalar</small><strong>${d.orders.length}</strong></div>${d.orders.length?d.orders.map(o=>ht`<article class="panel"><h2>${esc(o.restaurant_name)}</h2><p>${esc(o.restaurant_address)} → ${esc(o.delivery_address)}</p><p>${deliveryLabel(o.delivery_status)} · ${money(o.total)}</p><a class="primary" href="#/tracking/${esc(o.id)}">Buyurtma va GPS →</a></article>`).join(''):empty(t('Hozircha buyurtma yo‘q'),t('Restoran sizni buyurtmaga biriktirgach, shu yerda chiqadi.'))}<button class="quiet" id="refreshCourier">Yangilash</button>`}`);if($('#refreshCourier'))$('#refreshCourier').onclick=render}
function deliveryLabel(status){return {unassigned:t('Kuryer biriktirilmagan'),assigned:t('Kuryer biriktirilgan'),picked_up:t('Kuryer yo‘lda'),delivered:t('Yetkazilgan')}[status]||status}
let gpsWatch=null,gpsOrder=null,trackingTimer=null;
function stopTracking(){clearInterval(trackingTimer);trackingTimer=null;if(gpsWatch!==null&&navigator.geolocation)navigator.geolocation.clearWatch(gpsWatch);gpsWatch=null;if(gpsOrder){const id=gpsOrder;gpsOrder=null;api('/api/delivery','POST',{action:'stop',id}).catch(()=>{})}}
window.addEventListener('pagehide',stopTracking);
async function trackingPage(id,seq){if(!state.user){location.hash='/login';return}const d=await api('/api/delivery?id='+encodeURIComponent(id));if(seq!==state.seq)return;const o=d.order,courier=state.user.role==='courier'&&o.courier_id===state.user.id,manager=['restaurant_owner','admin'].includes(state.user.role)&&o.user_id!==state.user.id||state.user.role==='admin';page(t('Buyurtma va manzil'),ht`<a class="link" href="${courier?'#/courier':manager?'#/manage':'#/orders'}">← Panelga qaytish</a><div class="panel"><h2>${esc(o.restaurant_name)}</h2><p>Buyurtma: ${esc(o.id.slice(0,8))} · <strong>${money(o.total)}</strong></p><p>${JSON.parse(o.items).map(i=>ht`${esc(i.name)} × ${i.quantity}`).join(', ')}</p><p>Yetkazib berish: ${money(o.delivery_fee||0)}</p><div id="deliveryState"></div><p>To‘lov qabul qilish vaqtida. Holat to‘lovni tasdiqlamaydi.</p></div><div class="two"><section class="panel"><h2>Restoran manzili</h2><p>${esc(o.restaurant_address)}</p><a href="tel:${esc(o.restaurant_phone)}">${esc(o.restaurant_phone)}</a>${mapCard(o.restaurant_lat,o.restaurant_lng,o.restaurant_address)}</section>${o.fulfillment==='delivery'?ht`<section class="panel"><h2>Yetkazib berish manzili</h2><p>${esc(o.delivery_address)}</p><a href="tel:${esc(o.phone)}">${esc(o.phone)}</a>${mapCard(o.delivery_lat,o.delivery_lng,o.delivery_address)}</section>`:''}</div>${o.fulfillment==='delivery'?ht`<section class="panel"><h2>Kuryer joylashuvi</h2><div id="courierMap"></div><p class="muted">Faqat faol buyurtmada ulashilgan joy ko‘rsatiladi. Eskirgan GPS nuqtasi xaritada yashiriladi.</p></section>`:''}<section id="deliveryActions" class="panel"></section>`);
 const show=(order)=>{if(seq!==state.seq)return;$('#deliveryState').innerHTML=orderProgress(order);if($('#courierMap'))$('#courierMap').innerHTML=order.courier_lat!==null&&order.courier_lng!==null?ht`<p>Yangilandi: ${esc(new Date(order.location_at).toLocaleTimeString(RF_I18N.locale()))} · Aniqlik: ${Math.round(order.location_accuracy||0)} m</p>${mapCard(order.courier_lat,order.courier_lng,t('Kuryer joylashuvi'))}`:ht`<p>${order.status==='confirmed'?t('GPS ulashilmagan yoki oxirgi nuqta eskirgan.'):t('Kuzatuv faol emas.')}</p>`;};show(o);
 if(courier&&o.status==='confirmed'){
 $('#deliveryActions').innerHTML=ht`<h2>Yetkazib berishni boshqarish</h2><p>GPSni yoqsangiz joylashuvingiz mijoz va restoranga ko‘rinadi. Ushbu sahifani ochiq saqlang; ekran qulflansa yoki sahifadan chiqsangiz yangilanish to‘xtashi mumkin.</p><div class="row-actions"><button class="primary" id="startGps">GPS ulashishni yoqish</button><button class="quiet" id="stopGps">GPSni to‘xtatish</button><button class="primary" id="deliveryNext">${o.delivery_status==='assigned'?t('Taomni oldim'):t('Yetkazib berdim')}</button></div><p id="gpsMessage" role="status"></p>`;
 $('#startGps').onclick=()=>{if(!navigator.geolocation){notify(t('GPS mavjud emas.'));return}if(gpsWatch!==null)return;gpsOrder=id;let last=0,busy=false;$('#gpsMessage').textContent=t('GPS uchun ruxsat bering…');gpsWatch=navigator.geolocation.watchPosition(async p=>{if(gpsOrder!==id||busy||Date.now()-last<15000)return;busy=true;last=Date.now();try{await api('/api/delivery','POST',{action:'location',id,latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy});if($('#gpsMessage'))$('#gpsMessage').textContent=t('GPS ulashilmoqda. Oxirgi yuborish: ')+new Date().toLocaleTimeString(RF_I18N.locale())}catch(e){if($('#gpsMessage'))$('#gpsMessage').textContent=e.message}finally{busy=false}},()=>{if($('#gpsMessage'))$('#gpsMessage').textContent=t('GPS olinmadi. Telefon lokatsiyasi va brauzer ruxsatini tekshiring.')},{enableHighAccuracy:true,timeout:20000,maximumAge:5000})};
 $('#stopGps').onclick=()=>{stopTracking();$('#gpsMessage').textContent=t('GPS ulashish to‘xtatildi.')};$('#deliveryNext').onclick=async()=>{if(!confirm(o.delivery_status==='assigned'?t('Taomni restorandan oldingizmi?'):t('Buyurtmani mijozga yetkazdingizmi?')))return;try{await api('/api/delivery','POST',{id,action:o.delivery_status==='assigned'?'pickup':'complete'});render()}catch(e){notify(e.message)}};
 }else if(manager&&o.fulfillment==='delivery'&&o.status==='confirmed'&&['unassigned','assigned'].includes(o.delivery_status)){
 const c=await api('/api/delivery?couriers=1');if(seq!==state.seq)return;$('#deliveryActions').innerHTML=c.couriers.length?ht`<h2>Kuryerni biriktirish</h2><form id="assignCourier" class="form"><label>KURYER<select name="courierId">${c.couriers.map(c=>ht`<option value="${esc(c.id)}" ${o.courier_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><button class="primary">Biriktirish</button></form>`:lh('<p>Tasdiqlangan kuryer yo‘q. Administrator kuryer profilini tasdiqlashi kerak.</p>');if($('#assignCourier'))$('#assignCourier').onsubmit=async e=>{e.preventDefault();try{await api('/api/delivery','POST',{id,action:'assign',courierId:new FormData(e.currentTarget).get('courierId')});notify(t('Kuryer biriktirildi.'));render()}catch(e){notify(e.message)}};
 }else $('#deliveryActions').hidden=true;
 if(o.fulfillment==='delivery'&&o.status==='confirmed')trackingTimer=setInterval(async()=>{try{const d=await api('/api/delivery?id='+encodeURIComponent(id));if(seq!==state.seq)return;show(d.order);if(d.order.status!=='confirmed'){stopTracking();$('#deliveryActions').hidden=true;}}catch(e){if(seq===state.seq){stopTracking();notify(e.message)}}},20000);
}


window.addEventListener('rf-ai-cart',e=>{const d=e.detail,r=state.catalog.find(r=>r.id===d?.restaurantId);if(!r||!Array.isArray(d.items))return;const used=new Set(),items=d.items.filter(i=>{if(!i||used.has(i.id)||!Number.isInteger(i.quantity)||i.quantity<1||i.quantity>20)return false;used.add(i.id);return state.menu.some(m=>m.id===i.id&&m.restaurant_id===r.id&&m.available)}).slice(0,30).map(({id,quantity})=>({id,quantity}));if(!items.length)return;const current=readCart();if(current?.items.length&&!confirm(t(t('Tavsiya etilgan menyu bilan savat almashtirilsinmi?'))))return;state.cart={restaurantId:r.id,fulfillment:'pickup',items};saveCart();e.preventDefault();notify(t('Savatga qo‘shildi. Buyurtmani savatda tekshiring.'));});

function foodPicture(m){return ht`<div class="food-image">${m.image_url?ht`<img src="${esc(m.image_url)}" alt="${esc(m.name)}" loading="lazy" decoding="async">`:''}<span class="food-placeholder" ${m.image_url?'hidden':''} aria-label="${t(t('Rasm yo‘q'))}"><svg width="44" height="44" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="24" cy="24" r="15"/><circle cx="24" cy="24" r="10"/><path d="M3 9v12m4-12v12m-2 0v18M44 9v30M44 9c-6 4-6 14 0 14"/></svg></span></div>`}
function bindFoodImages(){document.querySelectorAll('.food-image img').forEach(img=>img.onerror=()=>{img.hidden=true;img.nextElementSibling.hidden=false})}
function foodUploadFields(m){return ht`<fieldset class="food-upload"><legend>Taom rasmi</legend><label>Rasm tanlash<input id="foodFile" type="file" accept="image/jpeg,image/png,image/webp"></label><p>JPG, PNG yoki WebP · 5 MB gacha · 4:3</p><div id="foodCurrent">${foodPicture(m||{})}</div><canvas id="foodCanvas" width="1200" height="900" hidden aria-label="Rasmni oldindan ko‘rish"></canvas><div id="foodCrop" hidden><label>Kattalashtirish<input id="cropZoom" type="range" min="1" max="3" step="0.01" value="1"></label><label>Gorizontal joylashuv<input id="cropX" type="range" min="0" max="100" value="50"></label><label>Vertikal joylashuv<input id="cropY" type="range" min="0" max="100" value="50"></label></div><button id="foodRemove" class="quiet" type="button">Rasmni olib tashlash</button><p id="foodError" role="status"></p></fieldset>`}
function bindFoodUpload(m){let bitmap=null,removed=false,revision=0;bindFoodImages();const file=$('#foodFile'),canvas=$('#foodCanvas'),controls=$('#foodCrop'),current=$('#foodCurrent'),error=$('#foodError');const draw=()=>{if(!bitmap)return;const scale=Math.max(1200/bitmap.width,900/bitmap.height)*Number($('#cropZoom').value),w=1200/scale,h=900/scale,x=(bitmap.width-w)*Number($('#cropX').value)/100,y=(bitmap.height-h)*Number($('#cropY').value)/100,ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,1200,900);ctx.drawImage(bitmap,x,y,w,h,0,0,1200,900)};['cropZoom','cropX','cropY'].forEach(id=>$('#'+id).oninput=draw);
file.onchange=async()=>{const generation=++revision,f=file.files[0];if(!f)return;const save=$('#dishForm button.primary');save.disabled=true;error.textContent='';try{if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5*1024*1024)throw Error(t(t('Rasm JPG, PNG yoki WebP va 5 MB dan kichik bo‘lsin.')));const next=await createImageBitmap(f);if(generation!==revision){next.close();return}if(next.width*next.height>40000000){next.close();throw Error(t(t('Rasm o‘lchami juda katta. Kichikroq rasm tanlang.')))}bitmap?.close();bitmap=next;removed=false;$('#cropZoom').value=1;$('#cropX').value=$('#cropY').value=50;canvas.hidden=controls.hidden=false;current.hidden=true;draw()}catch(e){file.value='';error.textContent=e.message||t(t('Rasm ochilmadi. Boshqa JPG yoki PNG tanlang.'))}finally{if(generation===revision)save.disabled=false}};
$('#foodRemove').onclick=()=>{revision++;bitmap?.close();bitmap=null;removed=true;file.value='';canvas.hidden=controls.hidden=true;current.hidden=false;current.innerHTML=foodPicture({});error.textContent='';$('#dishForm button.primary').disabled=false};
return {async save(restaurantId){if(!bitmap)return removed?'':m?.image_url||'';draw();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.88));if(!blob)throw Error(t(t('Rasm tayyorlanmadi.')));const response=await fetch('/api/media?restaurantId='+encodeURIComponent(restaurantId),{method:'POST',headers:{'Content-Type':'image/jpeg'},body:blob}),data=await response.json();if(!response.ok)throw Error(data.error||t(t('Rasm yuklanmadi.')));return data.url}}}

function readCart(){if(state.cart)return state.cart;try{const c=JSON.parse(localStorage.getItem('rf-cart')||'null');if(c&&typeof c.restaurantId==='string'&&Array.isArray(c.items)){state.cart={restaurantId:c.restaurantId,fulfillment:c.fulfillment==='delivery'?'delivery':'pickup',items:c.items.filter(i=>typeof i.id==='string'&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=20).slice(0,30)};return state.cart}}catch{}return null}
function saveCart(){try{if(state.cart?.items.length)localStorage.setItem('rf-cart',JSON.stringify(state.cart));else localStorage.removeItem('rf-cart')}catch{}mobileNavigation()}
function mobileNavigation(){const root=$('#mobileNav');if(!root)return;root.hidden=false;const count=readCart()?.items.reduce((s,i)=>s+i.quantity,0)||0;root.innerHTML=[['discover','⌂',t('Bosh sahifa')],['search','⌕',t('Qidiruv')],['cart','▣',t('Savat')],['account','♙',t('Profil')]].map(([id,icon,label])=>ht`<a href="#/${id}" ${routeName()===id?'aria-current="page"':''}><span aria-hidden="true">${navIcon(id)}</span>${esc(t(label))}${id==='cart'&&count?ht`<b>${count}</b>`:''}</a>`).join('')}
function bindMenuCart(r,menu){const form=$('#orderForm');if(!form)return;const cart=readCart();if(cart?.restaurantId===r.id)for(const i of cart.items){const input=form.elements.namedItem(i.id);if(input&&!input.disabled)input.value=i.quantity}form.querySelector('.form').innerHTML=lh('<a class="primary" href="#/cart">Savatga o‘tish →</a>');const update=e=>{if(e&&readCart()?.items.length&&state.cart.restaurantId!==r.id&&!confirm(t(t('Boshqa restoran tanlandi. Avvalgi savat almashtirilsinmi?')))){e.target.value=0;return}const items=menu.filter(m=>m.available).map(m=>({id:m.id,quantity:Number(form.elements.namedItem(m.id).value)})).filter(i=>Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=20);if(items.length||state.cart?.restaurantId===r.id){state.cart={restaurantId:r.id,items,fulfillment:(state.selectedFulfillment==='delivery'||catalogFilter.service==='delivery')&&r.delivery_enabled?'delivery':cart?.restaurantId===r.id?cart.fulfillment:'pickup'};saveCart()}$('#orderTotal').textContent=t(t('Taomlar'))+': '+money(items.reduce((sum,i)=>sum+menu.find(m=>m.id===i.id).price*i.quantity,0))};form.oninput=update;form.onsubmit=e=>{e.preventDefault();location.hash='/cart'};update()}
function cartQuote(cart,menu,r){const items=cart.items.map(i=>{const m=menu.find(m=>m.id===i.id&&m.restaurant_id===r.id&&m.available);return m?{...i,name:m.name,price:m.price}:null}),invalid=items.some(i=>!i),valid=items.filter(Boolean),subtotal=valid.reduce((s,i)=>s+i.price*i.quantity,0),fee=cart.fulfillment==='delivery'?Number(r.delivery_fee)||0:0;return {items:valid,invalid,subtotal,fee,total:subtotal+fee}}
async function cartPage(seq){await loadCatalog();if(seq!==state.seq)return;const cart=readCart(),r=state.catalog.find(r=>r.id===cart?.restaurantId);if(!cart?.items.length||!r){page(t('Savat'),empty(t('Savat bo‘sh'),t('Restoran menyusidan taom tanlang.'))+lh('<a class="primary" href="#/discover">Restoranlar</a>'));return}const q=cartQuote(cart,state.menu,r);page(t('Savat'),ht`<section class="panel compact"><h2>${esc(r.name)}</h2>${r.id.startsWith('rf-demo-')?lh('<p class="notice">DEMO: haqiqiy xizmat ko‘rsatilmaydi. Buyurtma va bronlar faqat sinov uchun.</p>'):''}<a class="link" href="#/restaurant/${encodeURIComponent(r.id)}">Menyuga qaytish</a>${q.invalid?lh('<p class="notice">Ayrim taomlar mavjud emas. Ular savatdan olib tashlandi.</p>'):''}<div class="rows">${q.items.map(i=>ht`<div class="row"><div><strong>${esc(i.name)}</strong><p>${money(i.price)} × ${i.quantity}</p></div><label>Soni<input class="qty" type="number" min="0" max="20" value="${i.quantity}" data-cart-qty="${esc(i.id)}" aria-label="${esc(i.name)}"></label><button class="link" data-cart-remove="${esc(i.id)}">O‘chirish</button></div>`).join('')}</div><form id="checkoutForm" class="form"><label>BUYURTMA TURI<select id="cartFulfillment"><option value="pickup">Olib ketish</option>${r.delivery_enabled?lh('<option value="delivery">Yetkazib berish</option>'):''}</select></label><div id="cartSummary" aria-live="polite"></div><label>TELEFON<input name="phone" type="tel" value="${esc(state.user?.contactPhone||state.user?.phone||'')}" pattern="\\+998[0-9]{9}" placeholder="+998901234567" required></label><div id="cartDelivery" class="form" hidden><label>YETKAZIB BERISH MANZILI<input id="cartAddress" minlength="5" maxlength="300"></label>${coordinateFields('cart')}</div><p>Buyurtma restoran tasdig‘ini kutadi. To‘lov qabul qilish vaqtida.</p>${state.user?ht`<button class="primary" id="placeOrder">${r.is_demo?t(t('Demo buyurtmani sinash')):t(t('Buyurtma yuborish'))}</button>`:lh('<a class="primary" href="#/login">Buyurtma uchun kiring</a>')}<p id="cartMessage" role="status"></p></form></section>`);cart.items=q.items.map(({id,quantity})=>({id,quantity}));if(!r.delivery_enabled)cart.fulfillment='pickup';saveCart();if(!cart.items.length){await cartPage(seq);return}$('#cartFulfillment').value=cart.fulfillment;const summary=()=>{cart.fulfillment=$('#cartFulfillment').value;saveCart();const v=cartQuote(cart,state.menu,r);$('#cartSummary').innerHTML=ht`<div class="row"><span>Taomlar</span><strong>${money(v.subtotal)}</strong></div><div class="row"><span>Yetkazib berish</span><strong>${money(v.fee)}</strong></div><div class="row"><span>Xizmat haqi</span><strong>${money(0)}</strong></div><div class="row"><strong>Jami</strong><strong>${money(v.total)}</strong></div>`;$('#cartDelivery').hidden=cart.fulfillment!=='delivery';$('#cartAddress').required=cart.fulfillment==='delivery'};summary();$('#cartFulfillment').onchange=summary;bindCoordinateButtons();document.querySelectorAll('[data-cart-qty]').forEach(input=>input.onchange=()=>{const n=Number(input.value);if(!Number.isInteger(n)||n<0||n>20){input.reportValidity();return}cart.items=cart.items.map(i=>i.id===input.dataset.cartQty?{...i,quantity:n}:i).filter(i=>i.quantity);saveCart();cartPage(seq)});document.querySelectorAll('[data-cart-remove]').forEach(b=>b.onclick=()=>{cart.items=cart.items.filter(i=>i.id!==b.dataset.cartRemove);saveCart();cartPage(seq)});$('#checkoutForm').onsubmit=async e=>{e.preventDefault();if(!state.user){location.hash='/login';return}if(r.is_demo||r.id.startsWith('rf-demo-')){const receipt=cartQuote(cart,state.menu,r);state.cart=null;localStorage.removeItem('rf-cart');page(t('Demo buyurtma'),ht`<section class="panel compact"><span class="demo-badge">DEMO</span><h2>${esc(r.name)}</h2><p>${t(t('Demo savat tekshirildi. Restoranga haqiqiy buyurtma yoki to‘lov yuborilmadi.'))}</p>${receipt.items.map(i=>ht`<p>${esc(i.name)} × ${i.quantity} — ${money(i.price*i.quantity)}</p>`).join('')}<strong>${t(t('Jami'))}: ${money(receipt.total)}</strong><p><a class="primary" href="#/discover">${t(t('Restoranlar'))}</a></p></section>`);mobileNavigation();return}const button=$('#placeOrder');button.disabled=true;try{const result=await api('/api/orders','POST',{restaurantId:r.id,items:cart.items,phone:e.currentTarget.elements.phone.value,fulfillment:cart.fulfillment,deliveryAddress:$('#cartAddress').value,deliveryLat:readCoord('cartLat'),deliveryLng:readCoord('cartLng')});state.cart=null;try{localStorage.removeItem('rf-cart')}catch{}notify(t('Buyurtma yuborildi: ')+money(result.total));location.hash='/tracking/'+encodeURIComponent(result.id)}catch(err){$('#cartMessage').textContent=err.message;button.disabled=false}}}
function orderProgress(o){if(o.status==='cancelled')return lh('<p class="notice">Bekor qilingan</p>');const delivery=o.fulfillment==='delivery',steps=[t('Qabul qilindi'),t('Tayyorlanmoqda'),delivery?t('Kuryerda'):t('Olib ketishga tayyor'),delivery?t('Yetkazildi'):t('Yakunlangan')];if(!delivery)steps.splice(2,1);const current=o.status==='completed'?steps.length-1:o.delivery_status==='picked_up'?2:o.status==='confirmed'?1:0;return ht`<ol class="order-progress" style="grid-template-columns:repeat(${steps.length},1fr)">${steps.map((step,i)=>ht`<li class="${i<=current?'done':''}" ${i===current?'aria-current="step"':''}><span>${i<current?'✓':i+1}</span>${esc(t(step))}</li>`).join('')}</ol>${o.status==='pending'?lh('<small>Restoran tasdig‘i kutilmoqda.</small>'):''}`}

function navIcon(id){const paths={discover:lh('<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3Z"/>'),search:lh('<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 5 5"/>'),cart:lh('<path d="M2 3h3l3 13h11l3-9H6"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/>'),account:lh('<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>')};return ht`<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">${paths[id]||''}</svg>`}

async function blogAdmin(seq){if(state.user?.role!=='admin'){page(t('Blog boshqaruvi'),empty(t('Ruxsat yo‘q'),t('Bu bo‘lim faqat sayt administratoriga ochiq.')));return}const d=await api('/api/blog');if(seq!==state.seq)return;page(t('Blog boshqaruvi'),ht`<a href="#/admin">← Admin panel</a><section class="panel"><label>${t(t('Maqola tanlang'))}<select id="blogSelect"><option value="">${t(t('Yangi maqola'))}</option>${d.posts.map(p=>ht`<option value="${esc(p.id)}">${esc(p.lang+' · '+p.title+' · '+p.status)}</option>`).join('')}</select></label><div id="blogEditor"></div></section>`);const editor=()=>{const p=d.posts.find(p=>p.id===$('#blogSelect').value);$('#blogEditor').innerHTML=ht`<form id="blogForm" class="form"><label>${t(t('Sarlavha'))}<input name="title" maxlength="160" minlength="5" required value="${esc(p?.title||'')}"></label><label>URL slug<input name="slug" pattern="[a-z0-9]+(-[a-z0-9]+)*" minlength="3" maxlength="100" required value="${esc(p?.slug||'')}"></label><p>${t(t('Tarjimalar uchun bir xil slug ishlating.'))}</p><label>${t(t('Sayt tili'))}<select name="lang">${['ru','uz','en'].map(l=>ht`<option ${l===(p?.lang||RF_I18N.lang)?'selected':''}>${l}</option>`).join('')}</select></label><label>${t(t('Qisqa tavsif'))}<textarea name="description" minlength="20" maxlength="320" required>${esc(p?.description||'')}</textarea></label><label>${t(t('Maqola matni'))}<textarea name="content" rows="18" minlength="100" maxlength="12000" required>${esc(p?.content||'')}</textarea></label><p>${t(t('Bo‘lim sarlavhasini ## bilan boshlang. Abzaslarni bo‘sh qator bilan ajrating. HTML ishlatilmaydi.'))}</p><label>${t(t('Holat'))}<select name="status"><option value="draft" ${p?.status!=='published'?'selected':''}>${t(t('Qoralama'))}</option><option value="published" ${p?.status==='published'?'selected':''}>${t(t('Nashr qilingan'))}</option></select></label><div class="row-actions"><button class="primary">${t(t('Maqolani saqlash'))}</button>${p?ht`<button type="button" class="quiet" id="deleteBlog">${t(t('O‘chirish'))}</button>${p.status==='published'?ht`<a href="/${p.lang}/blog/${esc(p.slug)}" target="_blank" rel="noopener">${t(t('Ko‘rish'))} →</a>`:''}`:''}</div><p id="blogMessage" role="status"></p></form>`;$('#blogForm').onsubmit=async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;try{await api('/api/blog','POST',{...Object.fromEntries(new FormData(e.currentTarget)),id:p?.id});notify(t('Saqlandi'));render()}catch(e){$('#blogMessage').textContent=e.message;button.disabled=false}};if($('#deleteBlog'))$('#deleteBlog').onclick=async()=>{if(!confirm(t(t('Maqola o‘chirilsinmi?'))))return;try{await api('/api/blog','POST',{action:'delete',id:p.id});render()}catch(e){notify(e.message)}}};$('#blogSelect').onchange=editor;editor()}
